import { useEffect, useState } from "react";
import { tracker } from "travel-platform";

// The consent choice was made before the session (necessary cookies only),
// so no banner renders; the tracker only reads and reports the state.
export function ConsentState() {
    const [consent] = useState({ necessary: true, analytics: false, marketing: false, version: 7 });
    useEffect(() => {
        tracker.push("sink", "consent.state", consent);
    }, [consent]);
    return null;
}
